"""Predeclared station availability using field presence and terrestrial headers."""
from copy import deepcopy
from decimal import Decimal
from itertools import combinations
import math

from .qualification import select_window


def eligible_epochs(structure):
    return {Decimal(e['seconds_gpst']) for e in structure.get('epochs', []) if e['eligible']}


def ground_position(structure):
    try:
        values = list(map(float, structure['header']['APPROX POSITION XYZ'][0].split()))
        offsets = list(map(float, structure['header']['ANTENNA: DELTA H/E/N'][0].split()))
        if len(values) != 3 or not all(math.isfinite(v) for v in values):
            return None
        if len(offsets) != 3 or not all(math.isfinite(v) for v in offsets):
            return None
        if not 6_000_000 <= math.sqrt(sum(v*v for v in values)) <= 6_500_000:
            return None
        return values
    except (KeyError, IndexError, TypeError, ValueError):
        return None


def aperture(positions):
    latitude = [math.degrees(math.atan2(p[2], math.hypot(p[0], p[1]))) for p in positions]
    baseline = max(math.dist(a, b) for a, b in combinations(positions, 2))
    return {'maximum_baseline_m': baseline, 'geocentric_latitude_span_deg': max(latitude)-min(latitude)}


def select_network(plan, structures):
    """Earliest qualifying window, then lexical seven-root subset; no target values."""
    if 'network' not in plan:
        selected = select_window(structures, plan['selection']['support_epochs'], plan['selection']['step_s'])
        selected['fit_stations'] = list(plan['fit_stations']) if selected['selected_seconds_gpst'] else None
        return selected
    policy = plan['network']
    names = policy['candidate_stations']
    withheld = plan['withheld_station']
    if set(structures) != set(names + [withheld]):
        raise ValueError('availability inventory differs from declared network')
    times = {n: eligible_epochs(structures[n]) for n in names + [withheld]}
    positions = {n: ground_position(structures[n]) for n in names}
    samples, step = plan['selection']['support_epochs'], plan['selection']['step_s']
    result = {'status': 'NO_COMMON_STRUCTURAL_WINDOW', 'selected_seconds_gpst': None,
              'fit_stations': None, 'withheld_station': withheld,
              'maximum_simultaneous_candidates_examined': 0, 'windows_with_seven_candidates': 0,
              'windows_rejected_by_ground_aperture': 0}
    if ground_position(structures[withheld]) is None:
        result['status'] = 'WITHHELD_STATION_UNAVAILABLE'
        return result
    for start in sorted(times[withheld]):
        window = {start + i*step for i in range(samples)}
        simultaneous = sum(start in times[n] for n in names)
        result['maximum_simultaneous_candidates_examined'] = max(result['maximum_simultaneous_candidates_examined'], simultaneous)
        if not window <= times[withheld]:
            continue
        candidates = [n for n in sorted(names) if positions[n] is not None and window <= times[n]]
        if len(candidates) < 7:
            continue
        result['windows_with_seven_candidates'] += 1
        for subset in combinations(candidates, 7):
            geometry = aperture([positions[n] for n in subset])
            if (geometry['maximum_baseline_m'] < policy['minimum_baseline_m'] or
                    geometry['geocentric_latitude_span_deg'] < policy['minimum_latitude_span_deg']):
                continue
            result.update(status='STRUCTURAL_NETWORK_AVAILABLE',
                          selected_seconds_gpst=[str(start+i*step) for i in range(samples)],
                          fit_stations=list(subset), ground_aperture=geometry)
            return result
        result['windows_rejected_by_ground_aperture'] += 1
    if result['windows_with_seven_candidates']:
        result['status'] = 'GROUND_APERTURE_NOT_QUALIFIED'
    return result


def effective_plan(plan, structure):
    """Resolve receiver roles again from the original frozen declaration."""
    if 'network' not in plan:
        return plan
    expected = select_network(plan, structure['structures'])
    if expected != structure['selection'] or expected['fit_stations'] is None:
        raise ValueError('selected network does not match the frozen rule')
    result = deepcopy(plan)
    result['fit_stations'] = expected['fit_stations']
    return result


def availability_report(plan, structure):
    selection = structure['selection']
    stations = []
    for name, info in sorted(structure['structures'].items()):
        times = sorted(eligible_epochs(info))
        longest = length = 0
        previous = None
        for time in times:
            length = length+1 if previous is not None and time-previous == plan['selection']['step_s'] else 1
            longest = max(longest, length)
            previous = time
        stations.append({'station': name, 'role': 'withheld' if name == plan['withheld_station'] else 'candidate',
                         'source_status': info.get('source_status', 'OBSERVATIONS_SCANNED'),
                         'source_reason': info.get('source_reason'), 'eligible_epochs': len(times),
                         'longest_consecutive_epochs': longest,
                         'ground_header_usable': ground_position(info) is not None})
    return {'schema': 'satellite-rf-availability-v1', 'target': plan['target'],
            'date_gpst': plan['date_gpst'], 'status': selection['status'],
            'ready_for_calibration': selection['selected_seconds_gpst'] is not None,
            'selected_fit_stations': selection.get('fit_stations'),
            'withheld_station': plan['withheld_station'],
            'selected_seconds_gpst': selection['selected_seconds_gpst'],
            'stations': stations,
            'scope': 'Field presence and terrestrial distribution only. Calibration, emitted-event alignment, identifiability, uncertainty and confirmation are not yet assessed.'}

sources/verification/qualification.py.content_utf8:
"""Bounded, value-blind qualification of predeclared inverse experiments.

No orbit inputs or numerical pseudorange parsing. RINEX 3 observation records
are not limited to 80 columns; missing trailing observation fields are blank.
"""
from __future__ import annotations

from decimal import Decimal
from datetime import date


class QualificationError(ValueError):
    pass


def scan_structure(content: str, target: str, date_gpst: str) -> dict:
    expected_date = date.fromisoformat(date_gpst)
    lines = iter(content.splitlines())
    types: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    headers: dict[str, list[str]] = {}
    system = ""
    for line in lines:
        label = line[60:80].strip()
        headers.setdefault(label, []).append(line[:60].rstrip())
        if label == "SYS / # / OBS TYPES":
            if line[0:1].strip():
                system = line[0]
                if system in counts:
                    raise QualificationError("duplicate observation type declaration")
                counts[system] = int(line[3:6])
                types[system] = []
            if not system:
                raise QualificationError("orphan observation type continuation")
            types[system].extend(line[7:60].split())
        if label == "END OF HEADER":
            break
    else:
        raise QualificationError("incomplete RINEX header")
    version = float(headers["RINEX VERSION / TYPE"][0][:9])
    if not 3 <= version < 4:
        raise QualificationError("expected RINEX 3")
    for system, count in counts.items():
        if len(types[system]) != count:
            raise QualificationError("incomplete observation types")
    gps_types = types.get("G", [])
    if not {"C1C", "C2W"}.issubset(gps_types):
        raise QualificationError("missing GPS C1C/C2W declarations")
    indices = [gps_types.index(code) for code in ("C1C", "C2W")]
    epochs = []
    events = []
    previous = None
    for line in lines:
        if not line.strip():
            continue
        if not line.startswith(">"):
            raise QualificationError("expected RINEX epoch")
        fields = line[1:].split()
        if len(fields) not in (8, 9):
            raise QualificationError("invalid epoch header")
        year, month, day, hour, minute = map(int, fields[:5])
        if (year, month, day) != (expected_date.year, expected_date.month, expected_date.day):
            raise QualificationError("epoch outside frozen date")
        second = Decimal(fields[5])
        time_s = Decimal(hour * 3600 + minute * 60) + second
        flag, record_count = map(int, fields[6:8])
        if flag == 4:
            updates = [next(lines, "") for _ in range(record_count)]
            # Phase-only updates do not change pseudorange or epoch tags.
            # Never silently ignore clock, coordinates, or code-type changes.
            if not all(row[60:80].strip() in ("SYS / PHASE SHIFT", "COMMENT") for row in updates):
                raise QualificationError("unhandled header update affecting code qualification")
            events.append({"seconds_gpst": str(time_s), "flag": flag, "records": updates})
            continue
        if previous is not None and time_s <= previous:
            raise QualificationError("non-increasing epoch time")
        previous = time_s
        if flag not in (0, 1):
            raise QualificationError("special event requires explicit interpretation")
        present = []
        seen = set()
        for _ in range(record_count):
            record = next(lines, None)
            if record is None or len(record) < 3 or not record[0].isalpha() or not record[1:3].isdigit():
                raise QualificationError("truncated or invalid satellite record")
            satellite = record[:3]
            if satellite in seen:
                raise QualificationError("duplicate satellite in epoch")
            seen.add(satellite)
            if satellite[0] != "G":
                continue
            # Deliberately no float conversion or range-quality filtering.
            if all(record[3 + 16 * i: 3 + 16 * i + 14].strip() for i in indices):
                present.append(satellite)
        target_present = target in present
        reference_count = sum(sv != target for sv in present)
        epochs.append({
            "seconds_gpst": str(time_s), "flag": flag,
            "receiver_clock_field_present": len(fields) == 9,
            "target_codes_present": target_present,
            "reference_code_count": reference_count,
            "eligible": flag == 0 and target_present and reference_count >= 4,
        })
    return {
        "header": headers, "gps_observation_types": gps_types,
        "epochs": epochs, "events": events,
        "epoch_count": len(epochs),
        "target_code_epoch_count": sum(e["target_codes_present"] for e in epochs),
        "eligible_epoch_count": sum(e["eligible"] for e in epochs),
    }


def select_window(structures: dict[str, dict], samples: int = 11, step: int = 30) -> dict:
    if not structures or samples < 1:
        raise QualificationError("empty selection")
    sets = [
        {Decimal(e["seconds_gpst"]) for e in s["epochs"] if e["eligible"]}
        for s in structures.values()
    ]
    common = set.intersection(*sets)
    selected = None
    for start in sorted(common):
        candidate = [start + i * step for i in range(samples)]
        if all(time in common for time in candidate):
            selected = [str(time) for time in candidate]
            break
    return {
        "common_eligible_epoch_count": len(common),
        "common_eligible_seconds_gpst": [str(t) for t in sorted(common)],
        "selected_seconds_gpst": selected,
        "status": "STRUCTURAL_WINDOW_PRESENT" if selected else "NO_COMMON_STRUCTURAL_WINDOW",
    }

sources/verification/solver.py.content_utf8:
"""Multi-receiver emitted-event multilateration: no target-state input surface."""
from __future__ import annotations

from itertools import combinations, product
import numpy as np
from scipy.optimize import least_squares, brentq

from .calibration import C, OMEGA, rotate_z, troposphere
from .errors import ScientificRejection

CHI95 = 7.814727903251179


def interpolate_event(codes, clocks, stations, u0=None, degree=3, time_offsets=None, times_s=None):
    codes, clocks, stations = map(np.asarray, (codes, clocks, stations))
    times = np.asarray(times_s if times_s is not None else np.arange(-150., 151., 30.), dtype=float)
    if codes.ndim != 2 or codes.shape != clocks.shape or codes.shape[1] != len(times) or len(times) % 2 != 1:
        raise ValueError("inconsistent code, clock and time arrays")
    if not np.isfinite(codes).all() or not np.isfinite(clocks).all() or not np.isfinite(times).all():
        raise ValueError("nonfinite event input")
    tagged_times = np.broadcast_to(times, codes.shape)
    if time_offsets is not None:
        tagged_times = tagged_times + np.asarray(time_offsets)
    tags = tagged_times - codes / C
    if u0 is None:
        u0 = float(np.median(tags[:, len(times)//2]))
    z, weights, positions = [], [], []
    for i, row in enumerate(tags):
        if np.any(np.diff(row) <= 0) or not row[0] <= u0 <= row[-1]:
            raise ScientificRejection("emission tags do not bracket event monotonically", 'SOURCE_OR_MEASUREMENT_NOT_QUALIFIED')
        selected = np.sort(np.argsort(abs(row - u0), kind="stable")[:degree + 1])
        nodes = row[selected]
        if not nodes[0] <= u0 <= nodes[-1]:
            raise ScientificRejection("interpolation stencil does not bracket event", 'SOURCE_OR_MEASUREMENT_NOT_QUALIFIED')
        w = np.ones(len(nodes))
        for j in range(len(nodes)):
            for k in range(len(nodes)):
                if j != k:
                    w[j] *= (u0 - nodes[k]) / (nodes[j] - nodes[k])
        full = np.zeros(len(times))
        full[selected] = w
        zi = float(full @ (codes[i] - clocks[i]))
        z.append(zi)
        weights.append(full)
        positions.append(rotate_z(stations[i], OMEGA * zi / C))
    return {"u0": u0, "z": np.array(z), "weights": np.array(weights), "positions": np.array(positions)}


def measurement_model(q, stations, atmosphere=True):
    q, stations = np.asarray(q), np.asarray(stations)
    ranges = np.linalg.norm(q[:3] - stations, axis=1)
    if atmosphere:
        delays = np.array([troposphere(s, q[:3])[0] for s in stations])
    else:
        delays = np.zeros(len(stations))
    return ranges + q[3] + delays


def model_jacobian(q, stations, atmosphere=True):
    delta = q[:3] - stations
    jac = np.column_stack((delta / np.linalg.norm(delta, axis=1)[:, None], np.ones(len(stations))))
    if atmosphere:
        for k in range(3):
            dq = np.zeros(4)
            dq[k] = 1.0
            plus = np.array([troposphere(s, q[:3] + dq[:3])[0] for s in stations])
            minus = np.array([troposphere(s, q[:3] - dq[:3])[0] for s in stations])
            jac[:, k] += (plus - minus) / 2
    return jac


def algebraic_seeds(z, stations):
    scale = 1e7
    y, s = np.asarray(z) / scale, np.asarray(stations) / scale
    def matrix(indices):
        yy, ss = y[indices], s[indices]
        a = np.column_stack((2 * (ss[1:] - ss[0]), -2 * (yy[1:] - yy[0])))
        rhs = (ss[1:]**2).sum(axis=1) - (ss[0]**2).sum() - (yy[1:]**2 - yy[0]**2)
        return a, rhs, yy, ss
    a, rhs, _, _ = matrix(list(range(len(y))))
    if np.linalg.matrix_rank(a) != 4:
        raise ScientificRejection("multi-root algebraic matrix is rank deficient")
    seeds = [np.linalg.lstsq(a, rhs, rcond=None)[0] * scale]
    for indices in combinations(range(len(y)), 4):
        a, rhs, yy, ss = matrix(list(indices))
        if np.linalg.matrix_rank(a) != 3:
            continue
        q = np.linalg.lstsq(a, rhs, rcond=None)[0]
        _, _, vh = np.linalg.svd(a)
        n = vh[-1]
        dx, b = q[:3] - ss[0], yy[0] - q[3]
        coefficients = [n[3]**2 - n[:3] @ n[:3], -2 * (b * n[3] + dx @ n[:3]), b*b - dx @ dx]
        for root in np.roots(coefficients):
            if abs(root.imag) < 1e-8:
                candidate = q + root.real * n
                if np.all(yy - candidate[3] > 0):
                    seeds.append(candidate * scale)
    return seeds


def refine(z, stations, covariance, seed, atmosphere=True):
    chol = np.linalg.cholesky(covariance)
    def residual(q):
        return np.linalg.solve(chol, measurement_model(q, stations, atmosphere) - z)
    def jac(q):
        return np.linalg.solve(chol, model_jacobian(q, stations, atmosphere))
    fit = least_squares(residual, seed, jac=jac, x_scale=np.full(4, 1e7), max_nfev=300, ftol=1e-12, xtol=1e-12, gtol=1e-10)
    singular = np.linalg.svd(jac(fit.x), compute_uv=False)
    return {"q": fit.x, "cost": float(residual(fit.x) @ residual(fit.x)), "success": bool(fit.success), "singular_values": singular, "residuals": measurement_model(fit.x, stations, atmosphere) - z}


def solve(z, stations, covariance, atmosphere=True):
    fits = []
    for seed in algebraic_seeds(z, stations):
        result = refine(z, stations, covariance, seed, atmosphere)
        if not result["success"] or not np.isfinite(result["q"]).all():
            continue
        q = result["q"]
        if atmosphere and min(troposphere(s, q[:3])[1] for s in stations) < 5:
            continue
        if np.any(z - q[3] <= 0):
            continue
        if all(np.linalg.norm(q - previous["q"]) > 0.1 for previous in fits):
            fits.append(result)
    if not fits:
        raise ScientificRejection("no admissible finite emitted-event solution")
    fits.sort(key=lambda v: v["cost"])
    best = fits[0]
    best["branches"] = [{"q": f["q"].tolist(), "cost": f["cost"]} for f in fits]
    best["ambiguous"] = any(f["cost"] - best["cost"] <= CHI95 for f in fits[1:])
    best["elevations_deg"] = [troposphere(s, best["q"][:3])[1] for s in stations] if atmosphere else []
    h = model_jacobian(best["q"], stations, atmosphere)
    _, sv, vh = np.linalg.svd(np.linalg.solve(np.linalg.cholesky(covariance), h), full_matrices=False)
    if sv[-1] <= sv[0] * 1e-12:
        raise ScientificRejection("position-clock Jacobian rank deficient")
    best["covariance"] = (vh.T / sv**2) @ vh
    return best


def profile_axes(z, stations, covariance, best):
    values, vectors = np.linalg.eigh(best["covariance"][:3, :3])
    chol = np.linalg.cholesky(covariance)
    radii = []
    for k in range(3):
        orth = vectors[:, [j for j in range(3) if j != k]]
        for sign in (-1, 1):
            direction = vectors[:, k] * sign
            def profile(distance):
                def residual(v):
                    q = best["q"].copy()
                    q[:3] += direction * distance + orth @ v[:2]
                    q[3] += v[2]
                    return np.linalg.solve(chol, measurement_model(q, stations) - z)
                def jac(v):
                    return np.column_stack([(residual(v + np.eye(3)[j]) - residual(v - np.eye(3)[j])) / 2 for j in range(3)])
                fit = least_squares(residual, np.zeros(3), jac=jac, x_scale=1000., max_nfev=100, ftol=1e-10, xtol=1e-10)
                return float(fit.fun @ fit.fun - best["cost"] - CHI95)
            upper = float(np.sqrt(CHI95 * values[k]) * 1.5)
            while profile(upper) < 0 and upper < 1e9:
                upper *= 2
            if upper >= 1e9:
                raise ScientificRejection("nonlinear confidence profile not bounded", 'UNCERTAINTY_NOT_QUALIFIED')
            radius = brentq(profile, 0.0, upper, xtol=0.01)
            radii.append({"axis": k, "sign": sign, "radius_m": float(radius)})
    return radii


def uncertainty_box(z, stations, covariance, best, bias_m=20., interior_samples=0, seed=2026250, margin=1.):
    displacements = []
    max_semiaxis = float(np.sqrt(CHI95 * np.linalg.eigvalsh(best["covariance"][:3, :3])[-1]))
    bias_probes = list(product((-1., 1.), repeat=len(z)))
    if interior_samples:
        bias_probes += np.random.default_rng(seed).uniform(-1, 1, (interior_samples, len(z))).tolist()
    for signs in bias_probes:
        shifted = z + bias_m * np.array(signs)
        corner = refine(shifted, stations, covariance, best["q"])
        if not corner["success"]:
            raise ScientificRejection("bias-box sensitivity fit did not converge", 'NUMERICAL_ASSESSMENT_FAILED')
        h = model_jacobian(corner["q"], stations)
        cw = np.linalg.solve(np.linalg.cholesky(covariance), h)
        _, singular, vh = np.linalg.svd(cw, full_matrices=False)
        cov = (vh.T / singular**2) @ vh
        max_semiaxis = max(max_semiaxis, float(np.sqrt(CHI95 * np.linalg.eigvalsh(cov[:3, :3])[-1])))
        displacements.append({"signs": list(signs), "delta_q": (corner["q"] - best["q"]).tolist()})
    profiles = profile_axes(z, stations, covariance, best)
    max_semiaxis = max(max_semiaxis, max(p["radius_m"] for p in profiles))
    bias_radius = max(np.linalg.norm(np.array(c["delta_q"])[:3]) for c in displacements)
    return {"bias_probes": displacements, "interior_samples": interior_samples, "margin": margin, "profile_axes": profiles, "statistical_95_radius_m": max_semiaxis, "bias_displacement_max_m": float(bias_radius), "total_95_outer_radius_m": float(margin * (max_semiaxis + bias_radius))}


def heldout_prediction(q, station, covariance_q):
    z = float(np.linalg.norm(q[:3] - station) + q[3])
    for _ in range(6):
        rotated = rotate_z(station, OMEGA * z / C)
        z = float(measurement_model(q, rotated[None, :])[0])
    h = model_jacobian(q, rotated[None, :])[0]
    variance = float(h @ covariance_q @ h)
    return z, variance


def far_field_cost(z, stations, covariance, q):
    """Cost at infinite range with free common clock: unit plane-wave direction."""
    direction = q[:3] / np.linalg.norm(q[:3])
    az = np.arctan2(direction[1], direction[0])
    el = np.arcsin(direction[2])
    chol = np.linalg.cholesky(covariance)
    def residual(v):
        n = np.array([np.cos(v[1]) * np.cos(v[0]), np.cos(v[1]) * np.sin(v[0]), np.sin(v[1])])
        from .calibration import geodetic
        delays = []
        for s in stations:
            _, _, height, up = geodetic(s)
            delays.append((2.3 * np.exp(-0.000116 * height) + 0.1) * 1.001 / np.sqrt(0.002001 + (up @ n)**2))
        return np.linalg.solve(chol, v[2] - stations @ n + np.array(delays) - z)
    initial_d = float(np.mean(z + stations @ direction))
    fit = least_squares(residual, [az, el, initial_d], x_scale=[1.,1.,1e7], max_nfev=300, ftol=1e-12, xtol=1e-12)
    return float(fit.fun @ fit.fun)
